use vstd::prelude::*;

verus! {
    // Splits a vector `a` into two vectors `a1` and `a2` satisfying:
    // 1. a1@ + a2@ == a@
    // 2. a1@.len() + a2@.len() == a@.len()
    // 3. if a@.len() > 1 then a1@.len() < a@.len() && a2@.len() < a@.len()
    fn array_split(a: Vec<i32>) -> (a1: Vec<i32>, a2: Vec<i32>)
        ensures
            a1@ + a2@ == a@,
        ensures
            a1@.len() + a2@.len() == a@.len(),
        ensures
            a@.len() > 1 ==>
                a1@.len() < a@.len() &&
                a2@.len() < a@.len(),
    {
        // We take ownership of `a` into `a2`.
        let mut a2 = a;
        // Capture the original sequence for the proof in the nontrivial branch.
        let old_seq: Seq<i32> = a2@;
        // If length is 0 or 1, just return (a2, empty).  This trivially satisfies all specs.
        if a2.len() <= 1 {
            return (a2, Vec::new());
        }
        // Otherwise, remove the first element into a1, and leave the rest in a2.
        let mut a1 = Vec::new();
        let x = a2.remove(0);
        a1.push(x);
        // Prove that concatenation is preserved.
        assert(old_seq == seq![x] + a2@);
        assert(a1@ + a2@ == old_seq);
        // The length facts will follow automatically:
        //   old_seq.len() == 1 + a2@.len(),
        //   a1@.len() == 1,
        //   so a1@.len() + a2@.len() == old_seq.len(),
        // and since old_seq.len() > 1, both 1 < old_seq.len() and old_seq.len() - 1 < old_seq.len().
        (a1, a2)
    }
}

